from __future__ import annotations

from fastapi.responses import HTMLResponse

from app.build_info import APP_VERSION, BUILD_ID


def reachability_page() -> HTMLResponse:
    return HTMLResponse(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Reachability</title>
<style>
:root{{--bg:#08141d;--panel:#0f1d27;--line:#294553;--text:#e7eef8;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b;color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:linear-gradient(135deg,#08141d,#10242e);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}}header,main{{max-width:1180px;margin:auto}}header{{position:sticky;top:0;z-index:100;padding:16px 0 14px;border-bottom:1px solid var(--line);background:rgba(8,20,29,.97);backdrop-filter:blur(14px)}}.sr-only{{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}}.nct-brand{{display:flex;width:max-content;flex-direction:column;align-items:center;margin:0 auto;line-height:1;text-align:center}}.nct-brand>strong{{padding-left:.24em;font-size:40px;letter-spacing:.24em}}.nct-brand span{{margin-top:3px;padding-top:3px;border-top:1px solid var(--accent);color:var(--muted);font-size:9px;font-weight:650;letter-spacing:.09em;text-transform:uppercase;white-space:nowrap}}.nct-brand span b{{color:var(--accent);font-size:1.16em;font-weight:950}}.nav{{display:flex;justify-content:center;gap:8px;margin-top:8px;flex-wrap:wrap}}.nav a{{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:6px 13px;text-decoration:none;font-weight:700}}.nav a.active{{background:var(--accent);border-color:var(--accent);color:#07171b}}main{{padding:24px 0 60px}}h2{{margin:0 0 7px;font-size:20px}}h3{{margin:0 0 6px;font-size:15px}}h4{{margin:12px 0 5px}}p{{margin:5px 0}}.panel{{background:rgba(15,29,39,.95);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 10px 35px #0003}}.query{{display:grid;grid-template-columns:1.2fr 1.2fr .55fr .55fr .8fr auto;gap:10px;align-items:end}}label{{display:block;color:#bed0da;font-size:12px;font-weight:750;margin:4px 0 5px}}input,select{{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}}button{{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 15px;font:inherit;font-weight:800;cursor:pointer}}button:disabled{{opacity:.5;cursor:not-allowed}}.hint,.meta,.empty{{color:var(--muted)}}.status{{min-height:22px;margin-top:10px;color:var(--muted)}}.status.good{{color:var(--good)}}.status.bad{{color:var(--bad)}}.status.warn{{color:var(--warn)}}.hidden{{display:none!important}}.result-head{{display:flex;gap:14px;align-items:start;justify-content:space-between}}.outcome{{font-size:26px;font-weight:900}}.outcome.local,.outcome.allowed{{color:var(--good)}}.outcome.routed{{color:var(--blue)}}.outcome.blocked{{color:var(--bad)}}.outcome.unknown{{color:var(--warn)}}.chip{{display:inline-block;border-radius:999px;padding:3px 8px;background:#243f4d;color:#cce1ea;font-size:11px;font-weight:750}}.two{{display:grid;grid-template-columns:1.25fr .75fr;gap:18px}}.path{{display:flex;align-items:stretch;gap:8px;overflow:auto;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}}.path-step{{min-width:150px;flex:1;background:#0a1720;border:1px solid #315264;border-radius:8px;padding:9px 10px}}.path-step strong{{display:block}}.path-arrow{{display:grid;place-items:center;color:var(--accent);font-size:20px;font-weight:900}}.evidence{{border-left:4px solid var(--blue);background:#0a1720;border-radius:7px;padding:10px 12px;margin:8px 0}}.evidence.policy{{border-left-color:var(--good)}}.evidence.service{{border-left-color:var(--accent)}}.evidence strong{{display:block}}ul{{margin:8px 0;padding-left:20px}}.legend{{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}}.legend div{{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}}.footer{{color:var(--muted);font-size:12px}}code{{color:#9edcff}}details.panel>summary{{position:relative;padding-left:25px;cursor:pointer;font-size:18px;font-weight:850;list-style:none}}details.panel>summary::-webkit-details-marker{{display:none}}details.panel>summary::before{{position:absolute;left:2px;top:50%;content:'▶';color:var(--accent);font-size:12px;transform:translateY(-50%);transition:transform .16s ease}}details.panel[open]>summary::before{{transform:translateY(-50%) rotate(90deg)}}details.panel[open]>summary{{margin-bottom:12px}}.actions{{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}}button.secondary{{background:transparent;border-color:#49617d}}.report-cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0}}.report-card{{padding:10px;border:1px solid var(--line);border-radius:8px;background:#0a1720}}.report-card strong{{display:block;color:var(--blue);font-size:20px}}.report-filters{{display:grid;grid-template-columns:1fr 1fr .8fr;gap:10px;align-items:end;margin:12px 0}}.check{{display:flex;align-items:center;gap:7px;min-height:42px}}.check input{{width:auto}}.report-source{{margin:9px 0;border:1px solid var(--line);border-radius:9px;background:#0a1720}}.report-source>summary,.report-result>summary{{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px;cursor:pointer;list-style:none}}.report-source>summary::-webkit-details-marker,.report-result>summary::-webkit-details-marker{{display:none}}.report-source>summary strong{{font-size:15px}}.report-results{{padding:0 10px 10px}}.report-result{{margin:7px 0;border:1px solid #315264;border-radius:8px;background:#0d1b24}}.report-result[open]>summary{{border-bottom:1px solid var(--line)}}.report-result-body{{padding:10px}}.report-result-title{{min-width:0}}.report-result-title strong,.report-result-title span{{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.report-chips{{flex-shrink:0;text-align:right}}.chip.expected-allowed{{background:#174b3c;color:#bdf4dc}}.chip.expected-blocked{{background:#542c32;color:#ffd0d5}}.chip.routed{{background:#173f5c;color:#bce4ff}}.chip.local{{background:#284632;color:#c8f1d2}}.chip.unknown{{background:#4a3d21;color:#ffe3a8}}.chip.not-exposed{{background:#263f54;color:#c9e6ff}}.chip.cve{{background:#4a3157;color:#f2d0ff}}.object-json{{max-height:220px;overflow:auto;padding:9px;border:1px solid var(--line);border-radius:7px;background:#07121a;color:#bce4ff;font-size:11px;white-space:pre-wrap}}@media(max-width:1200px){{header,main{{padding-left:4vw;padding-right:4vw}}}}@media(max-width:850px){{.query,.two,.legend,.report-cards,.report-filters{{grid-template-columns:1fr}}.path{{flex-direction:column}}.path-arrow{{transform:rotate(90deg)}}.report-source>summary,.report-result>summary{{align-items:flex-start;flex-direction:column}}.report-chips{{text-align:left}}}}
</style><style>.evidence.nat{{border-left-color:#c49aff}}.evidence.coverage{{border-left-color:var(--blue)}}.outcome.not.exposed{{color:var(--blue)}}</style><script src="/assets/nct-session.js" defer></script></head><body>
<header><h1 class="sr-only">Reachability</h1><div class="nct-brand" aria-label="NCT, Network Characterization Tool"><strong>NCT</strong><span><b>N</b>etwork <b>C</b>haracterization <b>T</b>ool</span></div><nav class="nav" aria-label="Primary"><a href="/device-config">Device</a><a href="/scans">Nmap</a><a href="/analysis">Analyze</a><a href="/hunting">Hunt</a><a class="active" href="/reachability" aria-current="page">Reach</a><a href="/network-map">Map</a></nav></header>
<main><section class="panel"><h2>Reachability Analysis</h2><p class="hint">Evaluate what the retained routes, device policy, Saved Networks, and Nmap service evidence support. This page does not send network traffic.</p><div class="query"><div><label for="source">Source</label><input id="source" list="sourceOptions" placeholder="Host, subnet, or Internet"><datalist id="sourceOptions"></datalist></div><div><label for="destination">Destination</label><input id="destination" list="destinationOptions" placeholder="Host, subnet, or Internet"><datalist id="destinationOptions"></datalist></div><div><label for="protocol">Protocol</label><select id="protocol"><option value="tcp">TCP</option><option value="udp">UDP</option></select></div><div><label for="port">Port</label><input id="port" type="number" min="1" max="65535" value="443"></div><div><label for="flowState">Flow state</label><select id="flowState"><option value="new">New connection</option><option value="established">Established / related</option></select></div><button id="evaluate">Evaluate</button></div><div id="status" class="status" role="status"></div></section>
<section id="result" class="hidden"><section class="panel"><div class="result-head"><div><div id="outcome" class="outcome"></div><p id="explanation"></p></div><div><span id="confidence" class="chip"></span><button id="showResultOnMap" class="secondary hidden" type="button">Show on Map</button></div></div><div id="path" class="path" aria-label="Likely path"></div></section><div class="two"><section class="panel"><h2>Evidence used</h2><div id="evidence"></div></section><section class="panel"><h2>Limits and uncertainty</h2><ul id="caveats"></ul></section></div></section>
<details id="exposureReportPanel" class="panel"><summary>Saved Network exposure reports</summary><p class="hint">Group every retained observed host service by Internet and Saved Network source. NCT reuses current scan, route, NAT, firewall, and local SearchSploit evidence; it sends no network traffic.</p><div class="actions"><button id="generateReport">Generate report</button><button id="exportReport" class="secondary" disabled>Export complete JSON</button></div><div id="reportStatus" class="status"></div><div id="reportSummary" class="report-cards hidden"></div><div id="reportFilters" class="report-filters hidden"><div><label for="reportSource">Source</label><select id="reportSource"><option value="">All sources</option></select></div><div><label for="reportOutcome">Reach outcome</label><select id="reportOutcome"><option value="">All outcomes</option></select></div><label class="check"><input id="reportCandidates" type="checkbox"> SearchSploit candidates only</label></div><p id="reportFilterCount" class="meta"></p><div id="exposureReports"></div></details>
<section class="panel"><h2>Outcome guide</h2><div class="legend"><div><h3>Local</h3><p class="meta">Both endpoints are in the same Saved Network. Local controls can still apply.</p></div><div><h3>Routed</h3><p class="meta">A retained route covers the destination, but policy is not established.</p></div><div><h3>Expected Allowed</h3><p class="meta">A supported explicit policy statement permits the exact service.</p></div><div><h3>Expected Blocked</h3><p class="meta">A supported explicit policy statement denies the exact service.</p></div><div><h3>Not Exposed</h3><p class="meta">Reserved for complete scan coverage that establishes the service was not exposed.</p></div><div><h3>Unknown</h3><p class="meta">The retained evidence cannot support an end-to-end conclusion.</p></div></div></section><div class="footer">Build <code>{APP_VERSION}</code> · <code>{BUILD_ID}</code></div></main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function setStatus(message,kind=''){{$('status').textContent=message;$('status').className='status '+kind}}
async function loadContext(){{try{{const response=await fetch('/api/reachability/context'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Reachability evidence is unavailable');const networks=data.saved_networks||[],hosts=data.hosts||[];const options=['Internet',...networks.map(n=>n.cidr),...hosts.map(h=>h.ip)].filter(Boolean);const markup=options.map(value=>`<option value="${{esc(value)}}"></option>`).join('');$('sourceOptions').innerHTML=markup;$('destinationOptions').innerHTML=markup;setStatus(`${{networks.length}} Saved Network${{networks.length===1?'':'s'}}, ${{hosts.length}} observed host${{hosts.length===1?'':'s'}}, and ${{data.device_collections||0}} current device collection${{data.device_collections===1?'':'s'}} available.`,'good')}}catch(error){{setStatus(error.message,'bad')}}}}
let latestReachResult=null;
const reachMapStorageKey='nct-reach-map-focus-v1';
function showOnMap(result,service=null,source=null){{if(!result)return;try{{sessionStorage.setItem(reachMapStorageKey,JSON.stringify({{version:1,created_at:new Date().toISOString(),result,service,source}}));location.href='/network-map?reach-focus=1'}}catch(error){{setStatus('This result could not be opened on Map in the current browser.','bad')}}}}
function render(data){{latestReachResult=data;$('result').classList.remove('hidden');$('showResultOnMap').classList.remove('hidden');const key=data.outcome.toLowerCase().replace('expected ','');$('outcome').textContent=data.outcome;$('outcome').className='outcome '+key;$('confidence').textContent=`${{data.confidence}} confidence`;$('explanation').textContent=data.explanation;$('path').innerHTML=(data.path||[]).map((item,index)=>`${{index?'<span class="path-arrow">→</span>':''}}<div class="path-step"><strong>${{esc(item.label)}}</strong><span class="meta">${{esc(item.detail||item.kind)}}</span></div>`).join('');$('evidence').innerHTML=(data.evidence||[]).map(item=>`<div class="evidence ${{esc(item.kind)}}"><strong>${{esc(item.title)}}</strong><span class="meta">${{esc(item.detail||'')}}</span>${{item.raw?`<br><code>${{esc(item.raw)}}</code>`:''}}</div>`).join('')||'<p class="empty">No supporting evidence matched this query.</p>';$('caveats').innerHTML=(data.caveats||[]).map(item=>`<li>${{esc(item)}}</li>`).join('')||'<li>No additional caveats were generated.</li>';}}
async function evaluate(){{const body={{source:$('source').value,destination:$('destination').value,protocol:$('protocol').value,port:Number($('port').value),flow_state:$('flowState').value}};setStatus('Evaluating retained evidence…');$('evaluate').disabled=true;try{{const response=await fetch('/api/reachability/evaluate',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Evaluation failed');render(data);setStatus('Reachability evaluation complete.','good')}}catch(error){{setStatus(error.message,'bad')}}finally{{$('evaluate').disabled=false}}}}
let exposureReport=null;
const outcomeClass=value=>String(value||'unknown').toLowerCase().replace(/\\s+/g,'-');
function reportPath(items){{return`<div class="path">${{(items||[]).map((item,index)=>`${{index?'<span class="path-arrow">→</span>':''}}<div class="path-step"><strong>${{esc(item.label)}}</strong><span class="meta">${{esc(item.detail||item.kind)}}</span></div>`).join('')}}</div>`}}
function reportEvidence(items){{return(items||[]).map(item=>`<div class="evidence ${{esc(item.kind)}}"><strong>${{esc(item.title)}}</strong><span class="meta">${{esc(item.detail||'')}}</span>${{item.raw?`<br><code>${{esc(item.raw)}}</code>`:''}}</div>`).join('')||'<p class="empty">No supporting evidence matched this path.</p>'}}
function candidateMarkup(service){{const info=service.searchsploit||{{}},candidates=info.candidates||[];if(!candidates.length)return'<p class="meta">No local SearchSploit candidates are associated with this service.</p>';return`<p>${{(info.cves||[]).map(cve=>`<span class="chip cve">${{esc(cve)}}</span>`).join('')||'<span class="chip cve">No CVE reference</span>'}}</p><ul>${{candidates.map(item=>`<li>${{item.url?`<a href="${{esc(item.url)}}" target="_blank" rel="noopener">EDB-${{esc(item.edb_id||'—')}}</a>`:`EDB-${{esc(item.edb_id||'—')}}`}} · ${{esc(item.title||'Untitled candidate')}}</li>`).join('')}}</ul>`}}
function reportResult(result,service,sourceId){{const product=[service.service,service.product,service.version].filter(Boolean).join(' · ')||'Unknown service',candidateCount=Number(service.searchsploit?.candidate_count||0),objects=result.retained_objects||{{}};return`<details class="report-result" data-outcome="${{esc(result.outcome)}}" data-candidates="${{candidateCount?'yes':'no'}}"><summary><span class="report-result-title"><strong>${{esc(service.ip)}}${{service.hostname?` · ${{esc(service.hostname)}}`:''}}</strong><span class="meta">${{esc(service.port)}}/${{esc(service.protocol)}} · ${{esc(product)}}</span></span><span class="report-chips"><span class="chip ${{outcomeClass(result.outcome)}}">${{esc(result.outcome)}}</span>${{candidateCount?`<span class="chip cve">${{candidateCount}} candidate${{candidateCount===1?'':'s'}}</span>`:''}}</span></summary><div class="report-result-body"><div class="actions"><button type="button" class="secondary show-report-on-map" data-reach-source="${{esc(sourceId)}}" data-reach-service="${{esc(result.service_key)}}">Show on Map</button></div><p>${{esc(result.explanation||'')}}</p>${{reportPath(result.path)}}<h4>Evidence</h4>${{reportEvidence(result.evidence)}}${{(result.caveats||[]).length?`<h4>Limits and uncertainty</h4><ul>${{result.caveats.map(item=>`<li>${{esc(item)}}</li>`).join('')}}</ul>`:''}}<h4>SearchSploit association</h4>${{candidateMarkup(service)}}<details><summary>Retained route, policy, and NAT objects</summary><pre class="object-json">${{esc(JSON.stringify(objects,null,2))}}</pre></details></div></details>`}}
function applyReportFilters(){{if(!exposureReport)return;const source=$('reportSource').value,outcome=$('reportOutcome').value,candidates=$('reportCandidates').checked;let visible=0;document.querySelectorAll('.report-source').forEach(group=>{{const sourceMatch=!source||group.dataset.source===source;let groupVisible=0;group.querySelectorAll('.report-result').forEach(row=>{{const show=sourceMatch&&(!outcome||row.dataset.outcome===outcome)&&(!candidates||row.dataset.candidates==='yes');row.classList.toggle('hidden',!show);if(show){{visible++;groupVisible++}}}});group.classList.toggle('hidden',!sourceMatch||!groupVisible);const count=group.querySelector('.visible-count');if(count)count.textContent=`${{groupVisible}} shown`}});$('reportFilterCount').textContent=`${{visible}} of ${{Number(exposureReport.evaluated_path_count||0)}} evaluated paths shown.`}}
function renderExposureReport(data){{exposureReport=data;const services=new Map((data.services||[]).map(item=>[item.service_key,item]));$('reportSummary').classList.remove('hidden');$('reportSummary').innerHTML=`<div class="report-card"><strong>${{Number(data.source_count||0)}}</strong><span>sources</span></div><div class="report-card"><strong>${{Number(data.service_count||0)}}</strong><span>unique observed services</span></div><div class="report-card"><strong>${{Number(data.evaluated_path_count||0)}}</strong><span>evaluated paths</span></div><div class="report-card"><strong>${{Number(data.searchsploit_candidate_count||0)}}</strong><span>SearchSploit candidates</span></div>`;$('reportFilters').classList.remove('hidden');$('reportSource').innerHTML='<option value="">All sources</option>'+(data.sources||[]).map(item=>`<option value="${{esc(item.source_id)}}">${{esc(item.name)}}${{item.cidr?` · ${{esc(item.cidr)}}`:''}}</option>`).join('');const outcomes=[...new Set((data.sources||[]).flatMap(source=>(source.results||[]).map(item=>item.outcome)))];$('reportOutcome').innerHTML='<option value="">All outcomes</option>'+outcomes.map(item=>`<option value="${{esc(item)}}">${{esc(item)}}</option>`).join('');$('exposureReports').innerHTML=(data.sources||[]).map((source,index)=>{{const countChips=Object.entries(source.counts||{{}}).filter(([,count])=>count).map(([outcome,count])=>`<span class="chip ${{outcomeClass(outcome)}}">${{esc(outcome)}} ${{Number(count)}}</span>`).join('');return`<details class="report-source" data-source="${{esc(source.source_id)}}" ${{index===0?'open':''}}><summary><span><strong>${{esc(source.name)}}</strong><span class="meta">${{source.cidr?` ${{esc(source.cidr)}} ·`:''}} <span class="visible-count">${{Number(source.service_count||0)}} shown</span></span></span><span>${{countChips}}</span></summary><div class="report-results">${{(source.results||[]).map(result=>reportResult(result,services.get(result.service_key)||{{}},source.source_id)).join('')||'<p class="empty">No retained observed services were available.</p>'}}</div></details>`}}).join('');document.querySelectorAll('.show-report-on-map').forEach(button=>button.onclick=event=>{{event.preventDefault();event.stopPropagation();const source=(data.sources||[]).find(item=>item.source_id===button.dataset.reachSource),result=(source?.results||[]).find(item=>item.service_key===button.dataset.reachService),service=services.get(button.dataset.reachService)||null;showOnMap(result,service,source)}});$('exportReport').disabled=false;$('reportStatus').textContent=`${{data.disclaimer||''}}${{(data.searchsploit?.warnings||[]).length?' SearchSploit: '+data.searchsploit.warnings.join(' '):''}}`;$('reportStatus').className='status '+((data.searchsploit?.warnings||[]).length?'warn':'good');applyReportFilters()}}
async function generateExposureReport(){{$('generateReport').disabled=true;$('reportStatus').textContent='Evaluating retained services from Internet and every Saved Network…';$('reportStatus').className='status';try{{const response=await fetch('/api/reachability/exposure-report',{{method:'POST'}}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Exposure report failed');renderExposureReport(data)}}catch(error){{$('reportStatus').textContent=error.message;$('reportStatus').className='status bad'}}finally{{$('generateReport').disabled=false}}}}
function exportExposureReport(){{if(!exposureReport)return;const stamp=new Date(exposureReport.generated_at||Date.now()).toISOString().replace(/[-:]/g,'').slice(0,15),blob=new Blob([JSON.stringify(exposureReport,null,2)],{{type:'application/json'}}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`NCT_Exposure_${{stamp}}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0)}}
$('evaluate').onclick=evaluate;$('showResultOnMap').onclick=()=>showOnMap(latestReachResult);$('generateReport').onclick=generateExposureReport;$('exportReport').onclick=exportExposureReport;for(const id of['reportSource','reportOutcome','reportCandidates'])$(id).addEventListener('change',applyReportFilters);loadContext();
</script></body></html>''')
